#!/bin/bash
# Download all data and models needed for this environment.
#
# Run on a node with internet access BEFORE building the container
# or submitting compute jobs.
#
# This script should be idempotent — safe to run multiple times.
# It should skip files that already exist.
#
# Update the storage estimate below as you add downloads.
#
# Estimated total download size: 0 GB
# Estimated disk usage after extraction: <1 MB
#
# This benchmark uses deterministic procedural data generated by the tracked
# data.split4d_synthetic module at method/evaluation time, so no external files
# are fetched.

set -e

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

mkdir -p data/generated data/downloads
cat > data/generated/manifest.json <<'EOF'
{
  "scenes": [
    "linear_motion",
    "interaction_motion"
  ]
}
EOF
echo "No external artifacts are required; procedural Split4D data is generated by tracked code."
